using System.Net;using System.Net.Http;using System.Reflection;using TownOfHost;using TownOfHost.Modules;
partial class Program{
static int streamNumber;static BindingFlags flags=BindingFlags.Static|BindingFlags.NonPublic;static string Html()=>"<script>ytcfg.set({\"INNERTUBE_API_KEY\":\"synthetic-key\",\"INNERTUBE_CONTEXT\":{\"client\":{\"clientVersion\":\"test-version\",\"visitorData\":\"synthetic-visitor\"}}});var ytInitialData="+new System.Text.Json.Nodes.JsonObject{["contents"]=new System.Text.Json.Nodes.JsonObject{["liveChatRenderer"]=new System.Text.Json.Nodes.JsonObject{["continuations"]=new System.Text.Json.Nodes.JsonArray(new System.Text.Json.Nodes.JsonObject{["timedContinuationData"]=new System.Text.Json.Nodes.JsonObject{["continuation"]="synthetic-next",["timeoutMs"]=3000}}),["actions"]=Actions(text:"join: Alice")}}}.ToJsonString()+";</script>";
static void ResetStream(){TownOfHost.Main.ShowStreamComments.Value=false;TownOfHost.Main.JoinWord.Value="join:";TownOfHost.Main.RemoveWord.Value="withdraw";YouTubeMapVote.Enabled=new(){Value=false};ExtraFeatureOptions.JoinByCommentOnly=new(){Value=false};AmongUsClient.Instance.AmHost=true;TownOfHost.GameStates.IsLobby=true;TownOfHost.GameStates.InGame=false;TownOfHost.Logger.Warnings.Clear();TownOfHost.Logger.Logs.Clear();typeof(StreamerInfo).GetField("lastErrorAt",flags).SetValue(null,DateTime.MinValue);StreamerInfo.TrySetStreamURL("https://youtu.be/"+(++streamNumber).ToString("D11"));}
static void Drain()=>typeof(StreamerInfo).GetMethod("DrainComments",flags).Invoke(null,null);
static void Queue(StreamerInfo info,string id,string channel,string text,bool live=true)=>typeof(StreamerInfo).GetMethod("Queue",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(info,new object[]{new[]{new LiveStreamComment(id,channel,"Viewer",text)},live});
static (StreamerInfo info,FakeHandler handler) FakeStream(params string[] replies){int epoch=(int)typeof(StreamerInfo).GetField("epoch",flags).GetValue(null);var info=(StreamerInfo)Activator.CreateInstance(typeof(StreamerInfo),BindingFlags.Instance|BindingFlags.NonPublic,null,new object[]{"AbCdef12_-3",epoch},null);var f=typeof(StreamerInfo).GetField("client",BindingFlags.Instance|BindingFlags.NonPublic);var original=(HttpClient)f.GetValue(info);var handler=new FakeHandler(replies);var mockClient=new HttpClient(handler);foreach(var header in original.DefaultRequestHeaders)mockClient.DefaultRequestHeaders.TryAddWithoutValidation(header.Key,header.Value);original.Dispose();f.SetValue(info,mockClient);typeof(StreamerInfo).GetField("current",flags).SetValue(null,info);return(info,handler);}
static void RunLifecycle(){
Test("stream URL canonical removes tracking",()=>{ResetStream();Check(StreamerInfo.TrySetStreamURL("https://youtu.be/AbCdef12_-3?si=tracking")&&StreamerInfo.StreamURL=="https://www.youtube.com/watch?v=AbCdef12_-3"&&TownOfHost.Main.StreamURLConfig.Value==StreamerInfo.StreamURL);});
Test("invalid URL does not replace valid stream",()=>{var old=StreamerInfo.StreamURL;Check(!StreamerInfo.TrySetStreamURL("https://evil.example/live")&&StreamerInfo.StreamURL==old);});
Test("URL alone does not enforce participation",()=>{ResetStream();Check(StreamerInfo.JoinPlayer(new(){PlayerName="Anyone"}));});
Test("explicit join-only filter uses live queue",()=>{ResetStream();ExtraFeatureOptions.JoinByCommentOnly.Value=true;var (i,h)=FakeStream();Queue(i,"1","viewer","join: Alice");Drain();Check(StreamerInfo.JoinPlayer(new(){PlayerName="Alice"})&&!StreamerInfo.JoinPlayer(new(){PlayerName="Other"}));StreamerInfo.StopNetwork();});
Test("empty join word does not enroll everyone",()=>{ResetStream();TownOfHost.Main.JoinWord.Value="";var (i,h)=FakeStream();Queue(i,"1","viewer","hello");Drain();Check(StreamerInfo.Hopeplayers.Count==0);StreamerInfo.StopNetwork();});
Test("empty channel cannot enroll",()=>{ResetStream();var (i,h)=FakeStream();Queue(i,"1","","join: Alice");Drain();Check(StreamerInfo.Hopeplayers.Count==0);StreamerInfo.StopNetwork();});
Test("initial HTML metadata parse and backfill work without commands",()=>{ResetStream();YouTubeMapVote.Enabled.Value=true;var (i,h)=FakeStream(Html());i.FetchAsync().GetAwaiter().GetResult();Check(StreamerInfo.RecentComments.Count==0);Drain();Check(StreamerInfo.RecentComments.Count==1&&StreamerInfo.Hopeplayers.Count==0&&h.Paths.Single().Contains("/live_chat?is_popout=1&v="));StreamerInfo.StopNetwork();});
Test("live acquisition posts serialized continuation",()=>{ResetStream();YouTubeMapVote.Enabled.Value=true;var (i,h)=FakeStream(Html(),Live(Actions(text:"!polus",id:"live2")));i.FetchAsync().GetAwaiter().GetResult();i.FetchAsync().GetAwaiter().GetResult();Check(h.Paths.Count==2&&h.Paths.All(x=>x.StartsWith("https://www.youtube.com/")));Drain();Check(YouTubeMapVote.Summary().Contains("Polus 1"));StreamerInfo.StopNetwork();});
Test("duplicate comments cannot double enqueue join",()=>{ResetStream();var (i,h)=FakeStream();Queue(i,"1","viewer","join: Alice");Queue(i,"1","viewer","join: Alice");Drain();Check(StreamerInfo.RecentComments.Count==1&&StreamerInfo.Hopeplayers.Count==1);StreamerInfo.StopNetwork();});
Test("viewer can update requested name without duplicate",()=>{ResetStream();var (i,h)=FakeStream();Queue(i,"1","viewer","join: Alice");Queue(i,"2","viewer","join: Bob");Drain();Check(StreamerInfo.Hopeplayers.Count==1&&StreamerInfo.Hopeplayers.Values.Single().PlayerName=="Bob");StreamerInfo.StopNetwork();});
Test("withdraw and sparse queue removal safe",()=>{ResetStream();var (i,h)=FakeStream();Queue(i,"1","a","join: Alice");Queue(i,"2","b","join: Bob");Queue(i,"3","a","withdraw");Drain();StreamerInfo.ChangeList(new(){"Bob"});Check(StreamerInfo.Hopeplayers.Count==0&&StreamerInfo.JoindHopeplayers.Count==1);StreamerInfo.StopNetwork();});
Test("nonhost receives comments but cannot change host queue or map",()=>{ResetStream();AmongUsClient.Instance.AmHost=false;YouTubeMapVote.Enabled.Value=true;var (i,h)=FakeStream();Queue(i,"1","viewer","join: Alice");Queue(i,"2","viewer","!polus");Drain();Check(StreamerInfo.RecentComments.Count==2&&StreamerInfo.Hopeplayers.Count==0&&!YouTubeMapVote.Summary().Contains("Polus 1"));StreamerInfo.StopNetwork();});
Test("old fetch generation discarded after stream change",()=>{ResetStream();var (i,h)=FakeStream();StreamerInfo.TrySetStreamURL("https://youtu.be/zzzzzzzzzzz");Queue(i,"1","viewer","join: Alice");Drain();Check(StreamerInfo.RecentComments.Count==0&&StreamerInfo.Hopeplayers.Count==0);});
Test("pending queue bounded at 512 and display history at30",()=>{ResetStream();var (i,h)=FakeStream();for(int n=0;n<600;n++)Queue(i,n.ToString(),"viewer","hello");Drain();Drain();Drain();Check(StreamerInfo.RecentComments.Count==30&&StreamerInfo.RecentComments.Last().Text=="hello");StreamerInfo.StopNetwork();});
Test("participation queue bounded at200",()=>{ResetStream();var (i,h)=FakeStream();for(int n=0;n<210;n++)Queue(i,n.ToString(),"viewer"+n,"join: Person"+n);Drain();Drain();Check(StreamerInfo.Hopeplayers.Count==200);StreamerInfo.StopNetwork();});
Test("oversized YouTube response rejected",()=>{ResetStream();var (i,h)=FakeStream(new string('x',2*1024*1024+1));bool denied=false;try{i.FetchAsync().GetAwaiter().GetResult();}catch(Exception e) when(e.Message=="YouTube comment retrieval failed"){denied=true;}Check(denied);StreamerInfo.StopNetwork();});
Test("all switches OFF makes zero requests and disposes current client",()=>{ResetStream();var (i,h)=FakeStream(Html());StreamerInfo.CommentFrameTick(.02f);Check(h.Paths.Count==0&&h.Disposed);});
Test("single flight and three second interval",()=>{ResetStream();TownOfHost.Main.ShowStreamComments.Value=true;var (i,h)=FakeStream(Html());for(int n=0;n<100;n++)StreamerInfo.CommentFrameTick(.02f);SpinWait.SpinUntil(()=>h.Paths.Count>0,2000);Thread.Sleep(50);for(int n=0;n<100;n++)StreamerInfo.CommentFrameTick(.02f);Check(h.Paths.Count==1);TownOfHost.Main.ShowStreamComments.Value=false;StreamerInfo.StopNetwork();});
Test("failure logs fixed message only",()=>{ResetStream();TownOfHost.Main.ShowStreamComments.Value=true;var (i,h)=FakeStream("malformed");StreamerInfo.CommentFrameTick(.02f);Check(SpinWait.SpinUntil(()=>TownOfHost.Logger.Warnings.Count>0,2000));Check(TownOfHost.Logger.Warnings.All(x=>!x.Contains("https://")&&!x.Contains("synthetic")&&!x.Contains("malformed")));TownOfHost.Main.ShowStreamComments.Value=false;StreamerInfo.StopNetwork();});
Test("disconnect cancels pending client and resets votes",()=>{ResetStream();YouTubeMapVote.Enabled.Value=true;YouTubeMapVote.OnComment("a","!polus");var (i,h)=FakeStream();StreamerInfo.DisconnectInternal();Check(h.Disposed&&!YouTubeMapVote.Summary().Contains("Polus 1"));});
}
class FakeHandler:HttpMessageHandler{readonly Queue<string> replies;public List<string> Paths=new();public bool Disposed;public HttpStatusCode ResponseStatus=HttpStatusCode.OK;public bool Timeout;public bool HangBody;public FakeHandler(string[] a){replies=new(a);}protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken ct){Paths.Add(r.RequestUri.AbsoluteUri);if(Timeout)throw new TaskCanceledException();if(HangBody)return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new HangingContent()});if(replies.Count==0)throw new InvalidOperationException();return Task.FromResult(new HttpResponseMessage(ResponseStatus){Content=new StringContent(replies.Dequeue())});}protected override void Dispose(bool disposing){Disposed=true;base.Dispose(disposing);}}
}
